package com.ruoyi.medical.persistence;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class TaskProfessionalPackageAuthoringMigrationTest {
 @Test void additiveProjectOnlyTablesCannotSeedCredentialsApprovalsOrModelCalls()throws Exception{String sql=Files.readString(Path.of("../medical-data/src/main/resources/db/migration/100-task-professional-package-authoring.sql"));for(String table:List.of("task_package_authoring_intent","task_package_authoring_registration","task_package_authoring_rejection")){assertTrue(sql.contains("CREATE TABLE "+table+" ("));}assertEquals(3,sql.split("CREATE TABLE ",-1).length-1);assertFalse(sql.contains("INSERT INTO"));assertFalse(sql.contains("ALTER TABLE"));assertTrue(sql.contains("FOREIGN KEY (tenant_id,project_id) REFERENCES project"));assertTrue(sql.contains("uq_task_package_key (tenant_id,created_by,original_key)"));assertTrue(sql.contains("PRIMARY KEY (tenant_id,created_by,original_key)"));assertTrue(sql.contains("REFERENCES operation_record (tenant_id,operation_id)"));assertTrue(sql.contains("REFERENCES artifact (tenant_id,artifact_id)"));assertTrue(sql.contains("'PROMPT','PROFILE','ROLE'"));assertTrue(sql.contains("REJECTED_PRE_INTENT"));}
 @Test void allThreeTablesRetainExplicitClassificationAndSchemaIdentity()throws Exception{String sql=Files.readString(Path.of("../medical-data/src/main/resources/db/migration/100-task-professional-package-authoring.sql"));for(String table:List.of("task_package_authoring_intent","task_package_authoring_registration","task_package_authoring_rejection")){String definition=sql.split("CREATE TABLE "+table+" \\(",2)[1].split(java.util.regex.Pattern.quote(") ENGINE="),2)[0];assertTrue(definition.contains("classification VARCHAR(24) NOT NULL"));assertTrue(definition.contains("schema_version VARCHAR(32) NOT NULL"));assertTrue(definition.contains("schema_manifest_sha256 CHAR(64) CHARACTER SET ascii NOT NULL"));assertTrue(definition.contains("'PUBLIC','INTERNAL','RESTRICTED','PERSONAL_HEALTH'"));}assertTrue(sql.contains("JSON_UNQUOTE(JSON_EXTRACT(proof_json,'$.classification'))=classification"));assertTrue(sql.contains("JSON_UNQUOTE(JSON_EXTRACT(proof_json,'$.schema_version'))=schema_version"));assertTrue(sql.contains("JSON_UNQUOTE(JSON_EXTRACT(proof_json,'$.schema_manifest_sha256'))=schema_manifest_sha256"));}
 @Test void frozenPublicContractBytesRemainUnchanged()throws Exception{byte[] bytes;try(var in=Objects.requireNonNull(getClass().getResourceAsStream("/task-professional-package-authoring.schema.json"))){bytes=in.readAllBytes();}assertEquals("urn:medical:task-professional-package-authoring:1.0.0",new com.fasterxml.jackson.databind.ObjectMapper().readTree(bytes).required("$id").textValue());assertEquals("4e1904ea23571d016a344ce4ef2212c202e8a4fad078cc7fcd305ec1d9b11e19",com.ruoyi.medical.contracts.WireValues.sha256(bytes));}
}
